async function renderFormFields(){try{const fields=await inspectForms(state.files[0]);const container=$('#form-fields');container.replaceChildren();if(!fields.length){const p=document.createElement('p');p.className='engine-status';p.textContent='No existing AcroForm fields found. You can add a new field above.';container.append(p);return;}for(const field of fields){if(field.type==='PDFSignature')continue;const row=document.createElement('div');row.className='form-field-row';const label=document.createElement('label');label.textContent=field.name;const input=field.type==='PDFDropdown'||field.type==='PDFOptionList'||field.type==='PDFRadioGroup'?document.createElement('select'):document.createElement('input');input.id='form-'+crypto.randomUUID();label.htmlFor=input.id;input.dataset.formField=field.name;if(input.tagName==='SELECT'){const empty=document.createElement('option');empty.value='';empty.textContent='Choose a value';input.append(empty);for(const option of field.options){const item=document.createElement('option');item.value=option;item.textContent=option;item.selected=Array.isArray(field.value)?field.value.includes(option):field.value===option;input.append(item);}}else if(field.type==='PDFCheckBox'){input.type='checkbox';input.checked=field.value;}else{input.type='text';input.value=field.value||'';}row.append(label,input);container.append(row);}}catch(error){notify(error.message,true);}}
function updateOverlay(){
  const id=state.tool?.id;const overlay=$('#position-overlay');if(!['edit','sign','redact'].includes(id)){overlay.hidden=true;return;}
  const value=(key,fallback)=>Number($('#option-'+key)?.value??fallback);overlay.hidden=false;overlay.classList.toggle('redaction',id==='redact');overlay.style.left=value('x',10)+'%';overlay.style.top=value('y',10)+'%';overlay.style.width=value('width',id==='sign'?30:40)+'%';overlay.style.height=value('height',10)+'%';overlay.textContent=id==='edit'?$('#option-text')?.value||'Your annotation':id==='sign'?'Signature':'';
}
function setBusy(busy){state.busy=busy;document.body.classList.toggle('processing',busy);$('#options-fields').disabled=busy;$('#progress-area').hidden=!busy;$('#run-tool').disabled=busy||state.loading||!state.files.length;for(const selector of ['#tool-files','#select-files','#clear-files','#add-more','#demo-file','#prev-page','#next-page'])$(selector).disabled=busy;$('#run-label').textContent=state.tool?.action||'';}
function releaseResults(){state.urls.forEach(URL.revokeObjectURL);state.urls=[];state.results=[];$('#result-preview').close();$('#result-preview-frame').removeAttribute('src');}
function download(blob,name){const url=URL.createObjectURL(blob),link=document.createElement('a');link.href=url;link.download=name;document.body.append(link);link.click();link.remove();setTimeout(()=>URL.revokeObjectURL(url),60000);}
function renderResults(result){
  releaseResults();state.results=result.outputs;$('#result-panel').hidden=false;$('#result-note').textContent=result.note||`${result.outputs.length} file${result.outputs.length===1?' is':'s are'} ready for your next big thing.`;$('#result-files').replaceChildren();
  result.outputs.forEach((file,index)=>{const row=document.createElement('div');row.className='result-file';row.innerHTML=`<span class="file-type-icon">${esc(file.name.split('.').pop().toUpperCase())}</span><div><strong>${esc(file.name)}</strong><small>${bytes(file.blob.size)} · ready to download</small></div>${file.blob.type==='application/pdf'?'<button class="secondary-button preview-output">Preview</button>':''}<button class="primary-button download-output">Download ↓</button>`;row.querySelector('.download-output').onclick=()=>download(file.blob,file.name);const preview=row.querySelector('.preview-output');if(preview)preview.onclick=()=>{const url=URL.createObjectURL(file.blob);state.urls.push(url);$('#result-preview-frame').src=url;$('#result-preview-title').textContent=file.name;$('#result-preview').showModal();};$('#result-files').append(row);});
  $('#download-all').hidden=result.outputs.length<2;$('#next-tool-area').hidden=!result.outputs.every(output=>output.blob.type==='application/pdf');$('#next-tool').innerHTML='<option value="">Use this PDF with another tool…</option>'+tools.filter(tool=>tool.input==='pdf').map(tool=>`<option value="${tool.id}">${tool.title}</option>`).join('');
  $('#result-panel').scrollIntoView({behavior:'smooth',block:'start'});
}
async function processFiles(){
  if(state.busy||state.loading||!state.files.length)return;
  const generation=state.generation,id=state.tool.id,options=readOptions();state.abort=new AbortController();setBusy(true);$('#result-panel').hidden=true;$('#run-progress').value=0;
  try{const result=await runTool(id,state.files,options,(message,progress)=>{if(generation!==state.generation)return;$('#progress-label').textContent=message;$('#run-progress').value=progress;},state.abort.signal);if(generation!==state.generation)return;renderResults(result);notify('All wrapped up. Your files are ready.');}
  catch(error){if(generation!==state.generation)return;if(error.name==='AbortError')notify('Processing canceled. Your original files are unchanged.');else{console.error('Processing failed:',error.name,error.message);notify(error.name==='EncryptedPDFError'?'This PDF is encrypted. Use Unlock PDF with its password first.':error.name==='PasswordException'?'This document needs its password. Use Unlock PDF first.':error.message||'This file could not be processed. Try a different document.',true);}}
  finally{if(generation===state.generation){setBusy(false);if(state.pdf){$('#prev-page').disabled=state.page===0;$('#next-page').disabled=state.page>=state.pdf.numPages-1;}}}
}
let drawing=false,lastPoint;
function clearSignature(){const canvas=$('#signature-canvas');canvas.getContext('2d').clearRect(0,0,canvas.width,canvas.height);state.signature=false;}
const sig=$('#signature-canvas');sig.onpointerdown=event=>{if(state.busy)return;event.preventDefault();drawing=true;sig.setPointerCapture(event.pointerId);const rect=sig.getBoundingClientRect();lastPoint={x:(event.clientX-rect.left)*sig.width/rect.width,y:(event.clientY-rect.top)*sig.height/rect.height};};sig.onpointermove=event=>{if(!drawing||state.busy)return;const rect=sig.getBoundingClientRect();const point={x:(event.clientX-rect.left)*sig.width/rect.width,y:(event.clientY-rect.top)*sig.height/rect.height};const ctx=sig.getContext('2d');ctx.strokeStyle='#42314f';ctx.lineWidth=3;ctx.lineCap='round';ctx.lineJoin='round';ctx.beginPath();ctx.moveTo(lastPoint.x,lastPoint.y);ctx.lineTo(point.x,point.y);ctx.stroke();lastPoint=point;state.signature=true;};sig.onpointerup=sig.onpointercancel=()=>{drawing=false;};$('#clear-signature').onclick=()=>{if(!state.busy)clearSignature();};
let regionStart;
$('#page-surface').onpointerdown=event=>{if(state.busy||state.tool?.id!=='redact')return;const rect=$('#page-surface').getBoundingClientRect();regionStart={x:Math.max(0,Math.min(100,(event.clientX-rect.left)/rect.width*100)),y:Math.max(0,Math.min(100,(event.clientY-rect.top)/rect.height*100))};$('#page-surface').setPointerCapture(event.pointerId);};$('#page-surface').onpointermove=event=>{if(!regionStart)return;const rect=$('#page-surface').getBoundingClientRect();const x=Math.max(0,Math.min(100,(event.clientX-rect.left)/rect.width*100)),y=Math.max(0,Math.min(100,(event.clientY-rect.top)/rect.height*100));for(const [key,value]of Object.entries({x:Math.min(x,regionStart.x),y:Math.min(y,regionStart.y),width:Math.max(.1,Math.abs(x-regionStart.x)),height:Math.max(.1,Math.abs(y-regionStart.y))}))$('#option-'+key).value=value.toFixed(2);updateOverlay();};$('#page-surface').onpointerup=$('#page-surface').onpointercancel=()=>{regionStart=null;};
function showInfo(){
  $('#info-content').innerHTML=`<div class="engine-status">${tools.length} working browser tools · No account · No daily quotas</div><h3>Private by design</h3><p>Your documents stay in this browser. Files are not uploaded to a document-processing server. Favorites and recent tool names are saved on your device; document contents and passwords are not saved. OCR downloads its engine and English language model on first use. Fonts load from Google Fonts.</p><h3>What “no limits” means</h3><p>Paperly adds no daily task quota, file-count cap, upload-size cap, or mandatory watermark. Your browser, device memory, canvas dimensions, and available storage still determine how much a job can process. Keep your original files, especially when working on signed documents: modifying a PDF can invalidate existing digital signatures.</p><h3>Available tools</h3><p>${tools.map(tool=>tool.title).join(' · ')}</p><h3>What needs more infrastructure</h3>${unavailable.map(([title,note])=>`<p><strong>${title}.</strong> ${note}</p>`).join('')}<h3>Format notes</h3><p>Office import converters preserve text or spreadsheet values, with reflowed layout. PDF-to-PowerPoint creates image-based slides. Form support covers standard AcroForm fields. Read each tool’s notes before processing. No third-party certification, AI service, or signing identity service is implied.</p><p><a href="./image-to-pdf/index.html">Open the original image-to-PDF workspace ↗</a></p>`;
  $('#info-dialog').showModal();
}
