$('#demo-file').onclick=async()=>{if(state.busy||state.loading)return;const doc=await PDFLib.PDFDocument.create();const font=await doc.embedFont(PDFLib.StandardFonts.Helvetica);for(let i=1;i<=3;i++){const page=doc.addPage([595.28,841.89]);page.drawText('Good things, all on one page.',{x:48,y:750,size:25,font,color:PDFLib.rgb(.47,.36,.78)});page.drawText(`Paperly studio notes - Page ${i}`,{x:48,y:710,size:12,font,color:PDFLib.rgb(.5,.45,.56)});page.drawText(`A little less paperwork. A little more possibility.`,{x:48,y:650,size:13,font});page.drawRectangle({x:48,y:430,width:490,height:150,color:PDFLib.rgb(.92,.88,.98)});page.drawText(`Project ${i}     Ready to share     2026`,{x:48,y:390,size:12,font});}const file=new File([await doc.save()],'paperly-sample.pdf',{type:'application/pdf'});await addFiles(state.tool.id==='compare'?[file,new File([await doc.save()],'paperly-sample-copy.pdf',{type:'application/pdf'})]:[file]);};
let dragDepth=0;const zone=$('#upload-zone');zone.ondragenter=event=>{if(!Array.from(event.dataTransfer.types).includes('Files'))return;event.preventDefault();dragDepth++;if(!state.busy&&!state.loading)$('#drop-indicator').hidden=false;};zone.ondragover=event=>{if(Array.from(event.dataTransfer.types).includes('Files')){event.preventDefault();event.dataTransfer.dropEffect=state.busy||state.loading?'none':'copy';}};zone.ondragleave=event=>{if(Array.from(event.dataTransfer.types).includes('Files')){dragDepth=Math.max(0,dragDepth-1);if(!dragDepth)$('#drop-indicator').hidden=true;}};zone.ondrop=event=>{if(!event.dataTransfer.files.length)return;event.preventDefault();dragDepth=0;$('#drop-indicator').hidden=true;addFiles(event.dataTransfer.files);};
window.addEventListener('dragover',event=>{if(Array.from(event.dataTransfer.types).includes('Files'))event.preventDefault();});window.addEventListener('drop',event=>{if(event.dataTransfer.files.length)event.preventDefault();});window.addEventListener('hashchange',route);window.addEventListener('keydown',event=>{if(event.key==='/'&&!['INPUT','TEXTAREA','SELECT'].includes(document.activeElement.tagName)&&!state.tool){event.preventDefault();$('#tool-search').focus();$('#tools').scrollIntoView({behavior:'smooth'});}});
renderDirectory();route();
